<script setup lang="ts">
import { ref, onMounted, computed } from 'vue'
import { api, post, labels } from '../api/client'
import { businessCopy } from '../presentation'
type Policy = { id: string; version: number; kind: string; valid_from: string; valid_until: string; conditions: { window_days: number; reasons?: string[] }; explanation: string }
const rows = ref<Policy[]>([]), selected = ref('refund'), error = ref(''), busy = ref(false), editing = ref(false)
const latest = computed(() => rows.value.find(row => row.kind === selected.value && row.version >= 3))
const draft = ref({ kind: 'refund', valid_from: '', valid_until: '', window_days: 7, allowed_reasons: [] as string[], require_received: false, explanation: '' })
async function load() { try { rows.value = (await api<{ items: Policy[] }>('/staff/policies')).items; error.value = '' } catch (e) { error.value = (e as Error).message } }
function edit() { if (!latest.value) return; const row = latest.value; draft.value = { kind: row.kind, valid_from: row.valid_from, valid_until: row.valid_until, window_days: row.conditions.window_days, allowed_reasons: [...(row.conditions.reasons || [])], require_received: ['exchange', 'repair'].includes(row.kind), explanation: businessCopy(row.explanation) }; editing.value = true }
async function publish() { busy.value = true; error.value = ''; try { await post('/staff/policies', draft.value); editing.value = false; await load() } catch (e) { error.value = (e as Error).message } finally { busy.value = false } }
onMounted(load)
</script>
<template><section class="panel policy-panel"><div class="panel-heading"><h3>售后政策</h3><el-button type="primary" :disabled="!latest" @click="edit">发布新版本</el-button></div><el-select v-model="selected" aria-label="政策类型"><el-option v-for="kind in ['refund', 'exchange', 'reship', 'repair']" :key="kind" :value="kind" :label="labels[kind]" /></el-select><div v-if="latest" class="policy-current"><h3>{{ labels[selected] }}政策 · v{{ latest.version }}</h3><p>{{ businessCopy(latest.explanation) }}</p><p>购买后 {{ latest.conditions.window_days }} 天内 · {{ latest.valid_from }} 至 {{ latest.valid_until }}</p></div><details><summary>历史版本</summary><div v-for="row in rows.filter(item => item.kind === selected)" :key="row.id + row.version" class="material-row"><strong>v{{ row.version }}</strong><p>{{ businessCopy(row.explanation) }}</p><span>{{ row.valid_from }} 至 {{ row.valid_until }}</span></div></details><p v-if="error" role="alert" class="error-text">{{ error }}</p><el-dialog v-model="editing" title="发布政策新版本" width="min(560px,94vw)"><el-form label-position="top" @submit.prevent="publish"><el-form-item label="有效期"><div class="preview-form-row"><input v-model="draft.valid_from" type="date" aria-label="政策开始日期" required /><input v-model="draft.valid_until" type="date" aria-label="政策结束日期" required /></div></el-form-item><el-form-item label="售后期限（从购买日计算）"><el-input-number v-model="draft.window_days" :min="0" :max="3650" /></el-form-item><el-form-item label="支持原因"><el-checkbox-group v-model="draft.allowed_reasons"><el-checkbox label="质量问题" value="quality" /><el-checkbox label="错发商品" value="wrong_item" /><el-checkbox label="未收到货" value="not_received" /><el-checkbox label="不想要了" value="changed_mind" /></el-checkbox-group></el-form-item><el-form-item label="政策说明"><el-input v-model="draft.explanation" type="textarea" :rows="4" maxlength="2000" /></el-form-item><p class="muted small">发布后保留历史版本。未办理申请将重新校验政策，条件变化时需要用户重新确认。</p><p v-if="error" class="error-text">{{ error }}</p><el-button type="primary" native-type="submit" :loading="busy" :disabled="!draft.explanation.trim() || !draft.allowed_reasons.length">确认发布新版本</el-button></el-form></el-dialog></section></template>
